package com.example.acres; import org.junit.jupiter.api.Test; import java.math.*; import static org.junit.jupiter.api.Assertions.*; class CalculationTest { @Test void remainingNeverNegative(){BigDecimal total=new BigDecimal("50");BigDecimal sold=new BigDecimal("52");assertEquals(BigDecimal.ZERO,total.subtract(sold).max(BigDecimal.ZERO));} @Test void progressCanExceedTarget(){BigDecimal progress=new BigDecimal("52").multiply(BigDecimal.valueOf(100)).divide(new BigDecimal("50"));assertEquals(new BigDecimal("104"),progress);} }
